387	    29	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
388	    30	        BigDecimal count = BigDecimal.valueOf(installments);
389	    31	        if (installments <= MAX_INTEREST_FREE) {
390	    32	            return new PaymentCharge(orderTotal, Money.round(orderTotal.divide(count, MathContext.DECIMAL128)));
