     1	package shop.payment;
     2	
     3	import shop.Money;
     4	
     5	import java.math.BigDecimal;
     6	import java.math.MathContext;
     7	
     8	public final class CreditCardPayment implements PaymentOption {
     9	    private static final int MAX_INSTALLMENTS = 12;
    10	    private static final int MAX_INTEREST_FREE = 3;
    11	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
    12	
    13	    @Override
    14	    public String code() {
    15	        return "CREDIT_CARD";
    16	    }
    17	
    18	    @Override
    19	    public boolean acceptsInstallments(int installments) {
    20	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
    21	    }
    22	
    23	    @Override
    24	    public boolean availableFor(BigDecimal orderTotal) {
    25	        return true;
    26	    }
    27	
    28	    @Override
    29	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
    30	        BigDecimal count = BigDecimal.valueOf(installments);
    31	        if (installments <= MAX_INTEREST_FREE) {
    32	            return new PaymentCharge(orderTotal, Money.round(orderTotal.divide(count, MathContext.DECIMAL128)));
    33	        }
    34	        // Price table: total * i / (1 - (1 + i)^-n)
    35	        BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(installments);
    36	        BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MathContext.DECIMAL128));
    37	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE).divide(divisor, MathContext.DECIMAL128));
    38	        return new PaymentCharge(installment.multiply(count), installment);
    39	    }
    40	}
