 4	
 5	public final class CreditReaction implements PaymentConfirmationReaction {
 6	    @Override
 7	    public void onPaid(Tx tx, Order order) {
 8	        tx.customers().addCredit(order.customerCpf(), order.summary().nextPurchaseCredit());
 9	    }
10	
11	    @Override
12	    public void onPaidOrderCancelled(Tx tx, Order order) {
13	        tx.customers().addCredit(order.customerCpf(), order.summary().nextPurchaseCredit().negate());
14	    }
